/**
 * Dictionary links between bundled nouns (links.json, generated by
 * tools/build-links.mjs from WordNet 3.1 and ConceptNet 5.7).
 *
 * The table is decoded on first use. Words are looked up exactly as typed
 * (trimmed, lower-cased); a word outside nouns.json has no links.
 */
import { LINK_RELATIONS, LINK_SOURCES, type LinkSource, type WordLink } from '../game';
import linksJson from './links.json';
import nounsJson from './nouns.json';

interface LinksFile {
  format: number;
  relations: string[];
  pairs: number[];
}

const data = linksJson as LinksFile;
const nouns: readonly string[] = nounsJson;

/** Base for pair keys: larger than any nouns.json index. */
const KEY_BASE = 65536;

let wordIndex: Map<string, number> | null = null;
let table: Map<number, number> | null = null;

function decode(): void {
  if (data.format !== 1) throw new Error(`links.json: unsupported format ${data.format}`);
  if (data.relations.length !== LINK_RELATIONS.length || data.relations.some((r, i) => r !== LINK_RELATIONS[i])) {
    throw new Error('links.json: relation list does not match LINK_RELATIONS; re-run npm run build-links');
  }
  if (nouns.length >= KEY_BASE) throw new Error('nouns.json is too large for the link table');
  wordIndex = new Map(nouns.map((w, i) => [w, i]));
  table = new Map();
  const p = data.pairs;
  for (let k = 0; k + 2 < p.length; k += 3) table.set(p[k]! * KEY_BASE + p[k + 1]!, p[k + 2]!);
}

/** Number of links in the bundled table. */
export function linkCount(): number {
  if (table === null) decode();
  return table!.size;
}

/**
 * The dictionary link between two words, or null if there is none. For a
 * directed relation, `from` and `to` follow the relation ("root" is part of
 * "tree") whichever order the words were given in; for a symmetric one they
 * keep the argument order.
 */
export function findLink(a: string, b: string): WordLink | null {
  if (table === null) decode();
  const x = a.trim().toLowerCase();
  const y = b.trim().toLowerCase();
  const ix = wordIndex!.get(x);
  const iy = wordIndex!.get(y);
  if (ix === undefined || iy === undefined || ix === iy) return null;
  const i = Math.min(ix, iy);
  const j = Math.max(ix, iy);
  const code = table!.get(i * KEY_BASE + j);
  if (code === undefined) return null;

  const relation = LINK_RELATIONS[code >> 4];
  if (relation === undefined) return null;
  const direction = (code >> 2) & 3;
  const sources: LinkSource[] = LINK_SOURCES.filter((_, bit) => (code & (1 << bit)) !== 0);
  if (sources.length === 0) return null;
  const from = direction === 1 ? nouns[i]! : direction === 2 ? nouns[j]! : x;
  const to = from === x ? y : x;
  return { relation, from, to, sources };
}
